inputs = ['ey', 'iaxh', 'we', 'kiwh', 'begjk']
outputs = ['evvkby', 'iaxh', 'wevvkb', 'kiwh', 'bevvkbgjk']

# Let's look at the actual differences more carefully
print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"Example {i}: '{inp}' -> '{outp}'")
        # Find where they differ
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        if len(inp) != len(outp):
            print(f"  Length change: {len(inp)} -> {len(outp)}")
        print()

